  Calendar, Printer, Layers, 
  PieChart as PieIcon, BarChart2, CheckSquare, Square, 
  GraduationCap, Crown, Calculator, TrendingUp, Target, 
  ChevronDown, User, FileText, Users, Award, Zap, Star, Flame, Minus, ShieldAlert,
  Trophy
} from 'lucide-react';
