          <div className="flex flex-wrap gap-2">
            {subjects.map(sub => (
              <FilterChip 
                key={sub}
                label={sub}
                active={selectedSubject === sub}
                onClick={() => setSelectedSubject(sub)}
                color="indigo"
              />
            ))}
          </div>
        </div>

        <div className="space-y-3 flex-1">
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2">
            <Filter className="w-3 h-3" /> {t('subject.select_classes')}
          </p>
          <div className="flex flex-wrap gap-2">
            {classes.map(cls => (
              <FilterChip 
                key={cls}
                label={cls}
                active={selectedClasses.includes(cls)}
                onClick={() => toggleClass(cls)}
                color="blue"
              />
            ))}
          </div>
        </div>
      </div>

      <ChartContainer title={t('subject.dist_title').replace('{subject}', selectedSubject).replace('{period}', selectedPeriod)}>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={distributionData} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
            <XAxis dataKey="name" stroke="#475569" fontSize={12} tick={{ fill: '#475569' }} />
            <YAxis stroke="#475569" fontSize={12} tick={{ fill: '#475569' }} />
            <Tooltip 
              cursor={{ fill: '#f8fafc' }}
              contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
              formatter={(value: number) => [`${value} ${t('common.participants')}`, t('common.participants')]}
            />
            <Bar dataKey="count" radius={[6, 6, 0, 0]} barSize={50}>
              {distributionData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
              <LabelList dataKey="count" position="top" style={{ fill: '#475569', fontSize: '12px', fontWeight: 'bold' }} />
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </ChartContainer>

      <div className="bg-white rounded-3xl border border-rose-100 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="px-8 py-6 bg-rose-50/50 border-b border-rose-100 flex items-center justify-between">
          <div>
            <h3 className="text-xs font-bold text-rose-600 uppercase tracking-widest flex items-center gap-2">
              <UserX className="w-4 h-4" /> {t('subject.focus_list')}
            </h3>
            <p className="text-[10px] text-rose-400 mt-1">
              {t('subject.focus_desc')
                .replace('{classes}', selectedClasses.join(', '))
                .replace('{subject}', selectedSubject)
                .replace('{count}', String(belowLineStudents.length))
              }
