                fill="#8b5cf6" 
                radius={[4, 4, 0, 0]} 
              />
              <Bar 
                dataKey="schoolFirst" 
                name={`${t('kings.legend_school_first')} - ${schoolFirstStudentName}`} 
                fill="#ec4899" 
                radius={[4, 4, 0, 0]} 
              />
            </BarChart>
          </ResponsiveContainer>
        </ChartContainer>
      </div>
    </div>
  );
};

